<?php require_once dirname(__DIR__).'/app/helpers.php';require_auth();require_once dirname(__DIR__).'/app/Services/ReportingService.php';$svc=new ReportingService(Database::connection());$rows=$svc->daily(30);$pageTitle='Account Insights';$currentPage='accounts';require __DIR__.'/partials/header.php';require __DIR__.'/partials/sidebar.php';?><div class="container py-4"><div class="d-flex justify-content-between align-items-center"><div><h2><?=e(t('Account').' Insights')?></h2><p class="text-muted">30-day simulated banking activity.</p></div><?=language_selector('form-select form-select-sm w-auto')?></div><div class="card border-0 shadow-sm"><div class="card-body"><table class="table"><thead><tr><th><?=e(t('Date'))?></th><th><?=e(t('Transactions'))?></th><th><?=e(t('Completed'))?></th><th><?=e(t('Failed'))?></th><th><?=e(t('Amount'))?></th></tr></thead><tbody><?php foreach(array_reverse($rows) as $r):?><tr><td><?=$r['day']?></td><td><?=$r['transactions']?></td><td><?=$r['completed']?></td><td><?=$r['failed']?></td><td><?=format_money((float)$r['volume'])?></td></tr><?php endforeach;?></tbody></table></div></div><a href="<?=url('dashboard.php')?>" class="btn btn-link mt-3">Back</a></div><?php require __DIR__.'/partials/footer.php';?>
